// HasProject applies the HasEdge predicate on the "project" edge.
func HasProject() predicate.XProjectStep {
	return predicate.XProjectStep(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ProjectTable, ProjectColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasProjectWith applies the HasEdge predicate on the "project" edge with a given conditions (other predicates).
func HasProjectWith(preds ...predicate.XProject) predicate.XProjectStep {
	return predicate.XProjectStep(func(s *sql.Selector) {
		step := newProjectStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.XProjectStep) predicate.XProjectStep {
	return predicate.XProjectStep(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.XProjectStep) predicate.XProjectStep {
	return predicate.XProjectStep(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.XProjectStep) predicate.XProjectStep {
	return predicate.XProjectStep(sql.NotPredicates(p))
}
